float inkHash(vec2 p) { return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453); }
float inkValue(vec2 p) {
 vec2 i=floor(p); vec2 f=fract(p); f=f*f*(3.0-2.0*f);
 return mix(mix(inkHash(i),inkHash(i+vec2(1.0,0.0)),f.x),mix(inkHash(i+vec2(0.0,1.0)),inkHash(i+vec2(1.0,1.0)),f.x),f.y);
}
vec4 inkNoise(vec2 p) {
 float n=inkValue(p*4.0)*.55+inkValue(p*8.2+vec2(17.2,3.1))*.3+inkValue(p*16.4+vec2(8.1,11.3))*.15;
 return vec4(n,n,n,1.0);
}

vec4 fxCustom(vec2 uv, vec4 tint, float life, float rnd, float age) {
 float head=mix(0.03,0.72,smoothstep(0.0,0.24,life));
 float tail=max(0.0,head-0.59*(1.0-smoothstep(0.31,1.0,life)));
 float arc=(uv.x-tail)/max(0.001,head-tail);
 float taper=pow(clamp(sin(clamp(arc,0.0,1.0)*3.14159),0.0,1.0),0.7);
 float n=inkNoise(vec2(uv.x*6.0-age*0.25,uv.y*2.3+rnd*3.0)).r;
 float fine=inkNoise(vec2(uv.x*3.6+0.3+n*.18,uv.y*3.2+rnd*4.0)).r;
 float inner=0.86-taper*0.86+(n-0.5)*0.26;
 float outer=0.91+(n-0.5)*0.15;
 float body=smoothstep(inner,inner+0.07,uv.y)*(1.0-smoothstep(outer-0.015,outer+0.015,uv.y));
 float grain=inkNoise(vec2(uv.x*15.0,uv.y*10.0+rnd*3.0)).r;
 float dry=(1.0-smoothstep(0.65,0.78,fine+life*0.09)*(1.0-smoothstep(0.68,0.93,uv.y)))*(1.0-smoothstep(.69,.8,grain)*.6);
 float erosion=smoothstep(life*0.48-0.1,life*0.48+0.17,n+uv.y*0.16);
 float ends=smoothstep(tail,tail+0.035,uv.x)*(1.0-smoothstep(head-0.02,head,uv.x));
 vec3 ink=mix(vec3(0.004,0.005,0.005),vec3(0.045,0.048,0.044),n*n*0.4);
 return vec4(ink*tint.rgb,body*ends*dry*erosion*tint.a);
}

