vec4 fxCustom(vec2 uv, vec4 tint, float life, float rnd, float age) {
 vec2 p=(uv-0.5)*2.0;
 float n=inkNoise(uv*2.8+vec2(rnd*8.1,age*.09)).r;
 float n2=inkNoise(uv*8.0+vec2(rnd*5.1,0.0)).r;
 float r=length(p);
 float edge=0.62+(n-.5)*.66;
 float body=1.0-smoothstep(edge-.08,edge+.04,r);
 float dry=smoothstep(life*.5-.08,life*.5+.13,n2);
 return vec4(tint.rgb,body*dry*tint.a);
}

